package main


import (
	"log"
	"net/http"


	"github.com/gorilla/websocket"
)


func main() {
	header := http.Header{}
	header.Set("Accept", "application/json")
	header.Set("X-API-Key", "<X-API-Key>")


	conn, _, err := websocket.DefaultDialer.Dial("wss://192.168.0.1/proxy/protect/integration/v1/subscribe/devices", header)
	if err != nil {
		log.Fatal("dial:", err)
	}
	defer conn.Close()


	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			log.Println("read:", err)
			return
		}
		log.Printf("recv: %s", message)
	}
}

local.nodejs:
const WebSocket = require("ws");


const ws = new WebSocket("wss://192.168.0.1/proxy/protect/integration/v1/subscribe/devices", {
  headers: {
    "Accept": "application/json",
    "X-API-Key": "<X-API-Key>",
  },
});


ws.on("open", () => console.log("connected"));
ws.on("message", (data) => console.log(data.toString()));
ws.on("close", () => console.log("disconnected"));
ws.on("error", (err) => console.error(err));

